// Cada cosa entra 0.2 s (6 cuadros) antes de su palabra (ant). La prueba (E3-E6) no se mueve: cruz en x=220 y punto en x=860, y=960.
export const SUBS={arriba:230,size:76,acento:'#E7FF00'};
const L='#E7FF00';
const A=[0,8,17,30,42,50,59,71,82,91,102,114,126,139,155].map(T);
const B=A.map((t,i)=>i?t-.15:0);
const ant=(w:string,n=1)=>en(w,n)-.2;
const q=(s:number,a:number,b:number,e:(x:number)=>number=Easing.inOut(Easing.cubic))=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:e});
const pls=(s:number,t0:number,d=.45)=>{const u=(s-t0)/d;return u<=0||u>=1?0:Math.sin(u*Math.PI);};
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const SK:[string,string,string]=['#f2c29c','#c98a5e','#7a4328'],HR:[string,string,string]=['#5a4644','#1e1414','#060404'],HD:[string,string,string]=['#ffa6cf','#FF2E88','#8a0a45'];
const VERDE:[string,string,string]=['#a8ff9f','#22b04a','#0b4a1c'],NAR:[string,string,string]=['#ffd29a','#ff8a1f','#a8420a'],LIMA:[string,string,string]=['#fbffb0',L,'#8a9600'];
